-- An append split (the general one and SQLite's balance_quick shape)
-- gives the right-most leaf a new right sibling while leaving the leaf
-- byte-identical, so append pins on it still validated: a pin carried
-- across statements then appended a LARGER rowid into the old leaf, past
-- the new separator (rows out of order, index entries orphaned — stateful
-- seed 878878, here a trigger INSERT inside a failing rowid-moving
-- UPDATE). The split now voids every pin on the old leaf.
CREATE TABLE t0 (c TEXT, b BLOB, c3 TEXT, pk INTEGER PRIMARY KEY);
CREATE TABLE audit (id INTEGER PRIMARY KEY, note TEXT);
CREATE TRIGGER trg0 AFTER UPDATE ON t0 BEGIN INSERT INTO audit (note) VALUES ('naïve'); END;
